  Object.assign(state,{bgeScene:'',bgeType:'total',bgeAmount:'',bgeCategory:'',bgeQuery:'',bgeError:'',bgeEditing:false,bgeHasTotal:false,bgeReadonly:false,bgeMode:'ready',bgeCurrency:'CNY'});
  const bgeCategories=[{id:'food',name:'餐饮',image:'utensils'},{id:'coffee',name:'自定义咖啡',image:'custom'},{id:'traffic',name:'交通',image:'train-front'}];
  const bgeScenes=[['budget-edit','添加预算','ready',false,'total',false,false,''],['budget-edit-existing-total','添加分类预算 · 已有总预算','ready',false,'category',true,false,''],['budget-edit-total','编辑总预算 · 保留原始精度','ready',true,'total',false,false,'2000.125'],['budget-edit-category','编辑分类预算','ready',true,'category',true,false,'500.00'],['budget-edit-custom','编辑预算 · 自定义分类图片','ready',true,'category',true,false,'300.25'],['budget-edit-empty-categories','添加预算 · 无可选父分类','empty-categories',false,'category',true,false,'120.00'],['budget-edit-loading','预算编辑 · 读取中','loading',false,'total',false,false,''],['budget-edit-error','预算编辑 · 读取失败','error',false,'total',false,false,''],['budget-edit-write-error','预算编辑 · 写入失败保留草稿','write-error',false,'total',false,false,'500.00'],['budget-edit-readonly','预算编辑 · 共享成员只读','ready',true,'category',true,true,'500.00']];
  function bgePrepare(key){const s=bgeScenes.find(s=>s[0]===key);if(s&&state.bgeScene!==key)Object.assign(state,{bgeScene:key,bgeMode:s[2],bgeEditing:s[3],bgeType:s[4],bgeHasTotal:s[5],bgeReadonly:s[6],bgeAmount:s[7],bgeCategory:s[3]&&s[4]==='category'?(key.includes('custom')?'coffee':'food'):'',bgeQuery:'',bgeError:''});}
  const bgeSymbol=()=>state.bgeCurrency==='USD'?'$':'¥';
  function bgeType(){return surface(`<div class="bge-types">${['total','category'].map(type=>btn('bge-type:'+type,type==='total'?bgtTexts.budgetTypeTotalLabel:bgtTexts.budgetTypeCategoryLabel,type==='total'?bgtTexts.budgetTypeTotalLabel:bgtTexts.budgetTypeCategoryLabel,'',`aria-pressed="${state.bgeType===type}" ${state.bgeReadonly||type==='total'&&state.bgeHasTotal?'disabled':''}`)).join('')}</div>`,'bge-type-card');}
  function bgeCategory(){const c=bgeCategories.find(c=>c.id===state.bgeCategory);return surface(btn('bge-category',`<span class="bge-category-icon">${c?.image==='custom'?'<img src="assets/category-coffee.png" alt="自定义分类图片">':icon(c?.image||'shapes')}</span><span><b>${esc(bgtTexts.budgetCategoryLabel)}</b><small>${esc(c?.name||bgtTexts.budgetCategoryHint)}</small></span>${state.bgeEditing?'':icon('chevron-right')}`,bgtTexts.budgetCategoryLabel,'bge-category',state.bgeReadonly||state.bgeEditing?'disabled':''),'bge-category-card');}
  function bgeAmount(){return surface(`<label class="bge-amount"><span>${esc(bgtTexts.budgetAmountLabel)}</span><span><b>${bgeSymbol()}</b><input data-bge-amount inputmode="decimal" aria-label="${esc(bgtTexts.budgetAmountLabel)}" placeholder="${esc(bgtTexts.budgetAmountHint)}" value="${esc(state.bgeAmount)}" ${state.bgeReadonly?'disabled':''}></span></label><p class="bge-error" ${state.bgeError?'':'hidden'}>${esc(state.bgeError)}</p>`,'bge-amount-card');}
  function bgePage(){const body=state.bgeMode==='loading'?'<div class="bge-empty" role="status">正在读取预算…</div>':state.bgeMode==='error'?`<div class="bge-empty"><p>错误：预算读取失败</p>${btn('bge-retry',bgtTexts.v4RecordingRetry,bgtTexts.v4RecordingRetry,'bc-primary')}</div>`:(state.bgeEditing?'':bgeType())+(state.bgeType==='category'?bgeCategory():'')+bgeAmount();return `<div class="bge-shell">${subhead(state.bgeEditing?bgtTexts.budgetEditTitle:bgtTexts.budgetAddTitle,state.bgeEditing&&!state.bgeReadonly?'bge-delete':'','trash-2').replace('更多操作',bgtTexts.commonDelete)}<div class="bge-scroll">${body}</div><footer class="bge-footer">${btn('bge-save',`${icon('check')}${esc(bgtTexts.commonSave)}`,bgtTexts.commonSave,'bc-primary',state.bgeReadonly||['loading','error'].includes(state.bgeMode)?'disabled':'')}</footer></div>`;}
  for(const[key,title]of bgeScenes){if(fDefs[key])fDefs[key].body=bgePage;else fDefine(key,title,'分类标签与预算','budget/budget_edit_page.dart',bgePage);}
  const bgePreviousRender=fRender;fRender=function(key){if(bgeScenes.some(s=>s[0]===key)){bgePrepare(key);return bgePage();}return bgePreviousRender(key);};
  rSpecs['bge-category']={title:bgtTexts.budgetCategoryLabel,host:'flow-budget-edit-existing-total',kind:'sheet'};rSpecs['bge-delete']={title:bgtTexts.commonDelete,host:'flow-budget-edit-total',kind:'dialog'};
  function bgePicker(){const rows=(state.bgeMode==='empty-categories'?[]:bgeCategories).filter(c=>c.name.toLowerCase().includes(state.bgeQuery.toLowerCase()));return `<div class="bge-picker"><label class="p-search-box">${icon('search')}<input data-bge-search value="${esc(state.bgeQuery)}" placeholder="${esc(bgtTexts.commonSearch)}" aria-label="${esc(bgtTexts.commonSearch)}"></label>${rows.map(c=>btn('bge-select:'+c.id,`<span class="bge-category-icon">${c.image==='custom'?'<img src="assets/category-coffee.png" alt="自定义分类图片">':icon(c.image)}</span><b>${esc(c.name)}</b>${state.bgeCategory===c.id?icon('check'):''}`,c.name,'',`aria-pressed="${state.bgeCategory===c.id}"`)).join('')||`<p>${esc(bgtTexts.budgetCategoryHint)}</p>`}</div>`;}
  const bgePreviousModal=rModalBody;rModalBody=function(key){return key==='bge-category'?bgePicker():key==='bge-delete'?`<p>${esc(bgtTexts.budgetDeleteConfirm)}</p>${rModalActions('r-close',bgtTexts.commonCancel,'bge-confirm-delete',bgtTexts.commonDelete).replace('bc-primary','bc-secondary bge-danger')}`:bgePreviousModal(key);};
  for(const[key,title]of [['bge-category','预算编辑 · 原分类底部选择'],['bge-delete','预算编辑 · 原删除确认']])fDefine(key,title,'分类标签与预算','budget/budget_edit_page.dart',()=>rModalBody(key));
  root.addEventListener('input',event=>{const el=event.target;if(el.matches('[data-bge-amount]')){if(event.isComposing){state.bgeAmount=el.value;return;}el.value=el.value.replaceAll('。','.').replaceAll('．','.').replace(/[^0-9.]/g,'').match(/^\d+\.?\d{0,2}/)?.[0]||'';state.bgeAmount=el.value;state.bgeError='';phone.querySelector('.bge-error').hidden=true;}else if(el.matches('[data-bge-search]')){const cursor=el.selectionStart;state.bgeQuery=el.value;rBuildModal();const input=phone.querySelector('[data-bge-search]');input.focus({preventScroll:true});input.setSelectionRange(cursor,cursor);}});
  root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el?.dataset.action.startsWith('bge-'))return;event.preventDefault();event.stopImmediatePropagation();const[action,value]=el.dataset.action.split(':');if(state.bgeReadonly)return;if(action==='bge-type'&&!(value==='total'&&state.bgeHasTotal)){state.bgeType=value;render();}else if(action==='bge-category'){state.bgeQuery='';rOpenModal('bge-category');}else if(action==='bge-select'){state.bgeCategory=value;rDismiss();render();}else if(action==='bge-delete')rOpenModal('bge-delete');else if(action==='bge-confirm-delete'){rDismiss();navigate(state.bgeType==='total'?'flow-budget-empty':'flow-budget');notice(bgtTexts.budgetDeleteSuccess,'success');}else if(action==='bge-retry'){state.bgeMode='ready';render();}else if(action==='bge-save'){const amount=Number(state.bgeAmount);if(!Number.isFinite(amount)||amount<=0){state.bgeError=bgtTexts.budgetAmountHint;render();return;}if(state.bgeType==='category'&&!state.bgeCategory){notice(bgtTexts.budgetCategoryHint,'error');return;}if(state.bgeMode==='write-error'){notice('错误：预算写入失败','error');return;}navigate('flow-budget');notice(bgtTexts.budgetSaveSuccess,'success');}},true);
